"""Offline document assembly; reads evidence and writes only the new supplement HTML."""
from pathlib import Path
import html
import json
import re

ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT.parent / 'transport-e2e-comparison'
original = (BASE / 'report.html').read_text()
# Preserve the original document, including all numeric rows, rebasing only evidence hrefs.
def rebase(match):
    value = match.group(1)
    return 'href="' + (value if value.startswith(('#', 'https:', 'http:', 'mailto:')) else '../transport-e2e-comparison/' + value) + '"'
report = re.sub(r'href="([^"]+)"', rebase, original)
report = report.replace('<title>Frozen Xray products — end-to-end TCP and loss-aware UDP comparison</title>', '<title>Frozen Xray products — original five workloads plus separate SS2022 → WireGuard supplement</title>')
framing = '''<section id="supplement-overview" aria-labelledby="supplement-title"><p class="muted">Expanded evidence report · original results preserved below</p><h1 id="supplement-title">Five original workloads + separately collected SS2022 → WireGuard</h1><p class="lead">48 primary result rows: the original 40 rows remain numerically unchanged; eight new rows complete the missing SS2022 → WireGuard chain.</p><div class="notice"><strong>Separate collection, not a joint 336-cell experiment.</strong> The original five workloads contain 280 timed cells. This supplement adds 56 separately collected timed cells (28 TCP + 28 UDP), each completed once with the same four frozen relay builds and unchanged final protocol-specific application drivers. The original and supplemental cohorts were not jointly interleaved. No cross-protocol capacity score or causal GSO/batching claim is implied.</div><nav aria-label="Supplement navigation"><a href="#supplement-method">Supplement route &amp; method</a><a href="#supplement-tcp">New TCP rows</a><a href="#supplement-udp">New UDP rows &amp; loss</a><a href="#supplement-evidence">Supplement evidence</a><a href="#products">Original pins &amp; report</a></nav><p><a href="../transport-e2e-comparison/report.html">Immutable original five-workload report</a> · All sections from the original report below describe the original cohort unless explicitly headed “Supplement”.</p></section>'''
report = report.replace('<body><main>', '<body><main>' + framing, 1)
names = {'official':'Official main','original-gso':'Original GSO fork','batching-only':'Our batching-only-era product','hybrid':'Our latest hybrid'}
order = list(names)
parts = ['''<section id="supplement-method"><h2>Supplement: SS2022 → WireGuard route and method</h2><p><strong>Actual route:</strong> application → fixed hybrid SS2022 outbound → candidate SS2022 inbound → candidate WireGuard outbound → fixed hybrid WireGuard gateway → virtual <code>10.77.0.1:19090</code> → echo <code>127.0.0.1:19090</code>. SS2022 cipher: <code>2022-blake3-aes-128-gcm</code>. The virtual destination is handled by the gateway userspace netstack/freedom redirect, not a namespace host route. Only the candidate relay product changes; fixed client and gateway use hybrid.</p><p>The four full commit and executable identities in the original <a href="#products">product table</a> apply unchanged; <a href="execution/plan-pins.json">supplement pin manifest</a> records those same exact commits and hashes. <a href="execution/configs/ss2022-wireguard-client.json">Client config</a> · <a href="execution/configs/ss2022-wireguard-relay.json">Candidate config</a> · <a href="execution/configs/gateway.json">Gateway config</a>.</p><ul><li>Same private-loopback Linux namespace setting and CPU split: candidate relay CPUs <code>2,3</code>, support client/gateway/application/echo CPUs <code>0,1</code>, <code>GOMAXPROCS=2</code>. Fixed support CPU contention can limit the chain. These are whole-build comparisons, not isolated optimization estimates or WAN results.</li><li>Seven predetermined matched rounds per protocol; 4 products × 7 rounds × 2 protocols = 56 timed cells, collected once with no timed DATA retry, rerun, retuning or new build. TCP and UDP remain separate protocol-specific experiments. Frozen source equivalence is recorded in <a href="execution/frozen-source-equivalence.json">source receipts</a>; actual source snapshots are <a href="execution/tcp/application.go.txt">TCP application</a> and <a href="execution/udp/application.go.txt">UDP application</a>.</li><li>TCP: 128 MiB (134,217,728 bytes) verified payload per direction, with 8 MiB warmup per direction excluded. Receiver-ready-to-final-verified-byte timing and deterministic payload checks are unchanged from the original final TCP driver.</li><li>Established RTT: 256 real 64-byte verified echoes per round after 32 warmups, measured before throughput without concurrent throughput. Fresh first response: 8 fresh-flow samples per round; pre-established support/WireGuard state is not a cold WireGuard handshake. Primary latency is the median of seven round medians, never the pooled request median.</li><li>UDP: 16,742,400 offered payload bytes per direction (436 × 32 × 1,200 bytes), zero DATA retransmissions. Same-route separate reliable TCP control carries progress/pull barriers and final receiver counters without assuming all UDP arrived. Upload cutoff is exactly 100 ms after the receiver's final reliable Q receipt; download cutoff is exactly 100 ms after the client's final D response. Receiver locking excludes observations at/after cutoff. Goodput is unique verified bytes divided by first-data-to-fixed-cutoff receiver duration, including control/barrier and drain overhead; this is not raw UDP capacity.</li><li>Every primary metric uses the median of seven round values, inclusive linear Q1–Q3, and median absolute deviation (MAD). Display rounding is three decimals; exact values are in attributes and summaries. The expandable tables retain exact min/max/MAD. Quartiles are dispersion, not confidence intervals.</li></ul><h3>Supplement smoke and preservation boundary</h3><p>All eight correctness-only smoke cells passed byte/loss accounting: TCP verified 1 MiB per direction; UDP offered 256 datagrams per direction and preserved actual missing datagrams rather than assuming delivery. Candidate syscall traces show real outer WireGuard UDP sends to <code>127.0.0.1:19100</code>; removing the gateway prevented verified echo within the 3-second negative-control window. These smoke traces are not timed samples. See <a href="smoke-reconciliation.json">smoke reconciliation</a>, <a href="audit/smoke-review.json">independent route/negative-control review</a>, <a href="smoke-tcp/raw.tar.gz">full TCP smoke corpus including traces and controls</a>, and <a href="smoke-udp/raw.tar.gz">full UDP smoke corpus including traces and controls</a>.</p><p><a href="execution/completion-receipts.json">Supplement completion/preservation receipts</a> show 28/28 TCP and 28/28 UDP cells complete, accepted pins/direct process affinity unchanged, original artifacts byte-identical, and sampled host namespace, IPv6 sysctls, IPv4/IPv6 routes and running-service states unchanged for these supplement captures. This does not erase the earlier original TCP caveat: <code>fwupd.service</code> disappeared between its passive snapshots (31 → 30 listed units), cause unobserved. Neither cohort supplies a contemporaneous manual/container production Xray PID/command identity before/after check; historical PID 1101327 is not such a check. Do not infer all-time service or PID preservation. No production edits or commits are part of this supplement.</p></section>''']
metrics = [('upload_Mbit_s','Upload goodput<br>Mbit/s'),('download_Mbit_s','Download goodput<br>Mbit/s'),('established_rtt_us','Established echo RTT<br>µs'),('setup_first_response_us','Fresh first response<br>µs')]
for network in ('tcp','udp'):
    summary = json.loads((ROOT / ('summary-' + network + '.json')).read_text())
    groups = {g['variant']:g for g in summary['groups']}
    active = metrics + ([('upload_loss_percent','Upload loss<br>%'),('download_loss_percent','Download loss<br>%')] if network == 'udp' else [])
    parts.append(f'<section id="supplement-{network}"><h2>Supplement: {network.upper()} · SS2022 → WireGuard</h2>')
    if network == 'udp':
        parts.append('<div class="notice"><strong>Loss is retained, not repaired.</strong> Official upload median loss is exactly 19.703268348623855%; original GSO upload median loss is exactly 20.0759747706422%; batching-era and hybrid upload median loss are 0%. Download loss is 0% for all four. These are medians of seven per-round loss rates, not aggregate percentages. Zero DATA retransmissions; no cross-protocol capacity comparison.</div>')
    parts.append(f'<div class="table-wrap"><table><caption>{network.upper()} · SS2022 → WireGuard · separate supplement · median (Q1–Q3)</caption><thead><tr><th scope="col">Candidate relay product</th>' + ''.join(f'<th scope="col">{label}</th>' for _,label in active) + '<th scope="col">Raw rounds</th></tr></thead><tbody>')
    for variant in order:
        g = groups[variant]
        parts.append(f'<tr data-protocol="{network}" data-case="ss2022-wireguard" data-variant="{variant}"><th scope="row">{names[variant]}</th>')
        for metric,_ in active:
            s = g[metric]
            parts.append(f'<td class="num" data-metric="{metric}" data-value="{s["median"]}" data-q1="{s["q1"]}" data-q3="{s["q3"]}">{s["median"]:.3f}<small>Q1–Q3 {s["q1"]:.3f}–{s["q3"]:.3f}</small></td>')
        parts.append('<td>' + ' '.join(f'<a href="timing-{network}/timing-{network}/{r["source"]}">{r["round"]}</a>' for r in g['rounds']) + '</td></tr>')
    parts.append('</tbody></table></div><details><summary>Exact supplemental dispersion: minimum, maximum and MAD over seven round values</summary><div class="table-wrap"><table><caption>' + network.upper() + ' · SS2022 → WireGuard · exact dispersion in the primary metric units</caption><thead><tr><th scope="col">Product</th><th scope="col">Metric</th><th scope="col">Minimum</th><th scope="col">Maximum</th><th scope="col">MAD</th></tr></thead><tbody>')
    for variant in order:
        for metric,_ in active:
            s = groups[variant][metric]
            parts.append(f'<tr><th scope="row">{names[variant]}</th><td><code>{metric}</code></td><td>{s["min"]}</td><td>{s["max"]}</td><td>{s["mad"]}</td></tr>')
    parts.append(f'</tbody></table></div></details><p><a href="summary-{network}.json">Exact supplemental {network.upper()} summary and seven round values</a> · <a href="audit/independent-results.json">Independent raw-derived distributions and UDP loss/duplicate/corrupt counters</a>.</p></section>')
parts.append('''<section id="supplement-evidence"><h2>Supplement evidence index</h2><p><a href="audit/reconciliation.json">Independent reconciliation</a> reconstructed all 56 raw timing cells / 8 groups and matched 1,400 numeric summary values. Producer UDP summaries omit the all-zero corrupt-datagram fields; <a href="audit/independent-results.json">independent results</a> retain them. This is an arithmetic/source audit, not an assertion of performance generalization.</p><ul>''')
for path,label in [('summary-tcp.json','Exact TCP primary summary'),('summary-udp.json','Exact UDP primary summary'),('audit/reconciliation.json','Independent arithmetic reconciliation'),('audit/independent-results.json','Independent full distributions/counters'),('audit/smoke-review.json','Independent smoke route/negative controls'),('smoke-reconciliation.json','Smoke accounting and pins'),('execution/plan-pins.json','Plan, exact product pins and prior host caveat'),('execution/completion-receipts.json','Timing completion and preservation'),('timing-tcp/timing-tcp/index.json','All 28 TCP raw cell index'),('timing-udp/timing-udp/index.json','All 28 UDP raw cell index'),('timing-tcp/timing-tcp/environment.json','TCP environment and source/binary pins'),('timing-udp/timing-udp/environment.json','UDP environment and source/binary pins'),('timing-tcp/raw.tar.gz','Full TCP timing corpus'),('timing-udp/raw.tar.gz','Full UDP timing corpus'),('smoke-tcp/raw.tar.gz','Full TCP smoke corpus/traces/negative controls'),('smoke-udp/raw.tar.gz','Full UDP smoke corpus/traces/negative controls')]:
    parts.append(f'<li><a href="{html.escape(path)}">{html.escape(label)}</a></li>')
parts.append('</ul><p>The original 40 rows and their evidence remain the original experiment; the eight rows above are the separate SS2022 → WireGuard supplement. Both are shown without normalization, pooled replacement, or a combined capacity ranking.</p></section>')
report = report.replace('<footer>', '\n'.join(parts) + '<footer>', 1)
report = report.replace('<nav aria-label="Supplement navigation">', '<nav aria-label="Supplement navigation"><a href="#ss2022-wireguard-supplement">SS2022 → WireGuard (TCP + UDP supplement)</a>', 1)
report = report.replace('<section id="supplement-method">', '<section id="ss2022-wireguard-supplement" aria-label="SS2022 → WireGuard TCP and UDP supplement"><section id="supplement-method">', 1)
report = report.replace('</section><footer>', '</section></section><footer>', 1)
(ROOT / 'report.html').write_text(report)
print('Created', ROOT / 'report.html')
